           /**************************************************************************
            * function    : init
            * Description : 서브 메인 화면 초기화
            * Parameter   : 
            * Return      : 
            **************************************************************************/
	        function init() {
				this.document.title=divisionNm;
				resizeIframe();

				getMaxTradeYmd();
				var tradeYmd = getValue("respMaxTradeYmd/root/message/BISTypRemTrmWhtAvgDTO/tradeYmd");
				tradeYmd = (tradeYmd == null || tradeYmd=="") ? WebSquare.date.getCurrentServerDate( "yyyyMMdd" ) : tradeYmd;
				schTradeYmd.setValue(tradeYmd);
				searchData();
			}

        	/**************************************************************************
             * function    : callBack
             * Description : submission 실행 후 Callback
             * Parameter   : retAction(submission 실행 Action), rowCount(조회 목록 총 건수)
             * Return      : null
             **************************************************************************/
        	function callBack(svcId,fnId,strResp,acount) {   
        		if (svcId == "BISTypRemTrmWhtAvgSrchSO") {
        			if(fnId="selectList") {
        				var isNew = (getValue("BISTypRemTrmWhtAvgDTO/val1")=="N") ? true:false;
        				aCnt=getValue("respList/root/message/BISTypRemTrmWhtAvgListDTO/dbio_total_count_");
        				(isNew)? showGrid():showGridOld();
        				resizeIframe();
        			}
        		}
            }

            /**************************************************************************
             * function    : getMaxTradeYmd
             * Description : 조회일 최대값 조회
             * Parameter   : 
             * Return      : null
             **************************************************************************/
        	function getMaxTradeYmd() {
		        callProFrameAdvanced("BIS-KOFIABOND","BISTypRemTrmWhtAvgSrchSO","selectMaxTradeYmd","", "respMaxTradeYmd", false);
        	}            

            /**************************************************************************
             * function    : searchData
             * Description : 데이터 조회
             * Parameter   : null
             * Return      : null
             **************************************************************************/
        	function searchData() {
				var tradeYmd=schTradeYmd.getValue();
				if( !isValidDate(tradeYmd)){ showMsg("C_I029"); return; }
				if(tradeYmd >= "20061218") {setValue("BISTypRemTrmWhtAvgDTO/val1","N");}else{setValue("BISTypRemTrmWhtAvgDTO/val1","O");};
				if(tradeYmd >= "20090204") {setValue("BISTypRemTrmWhtAvgDTO/val2","N");}else{setValue("BISTypRemTrmWhtAvgDTO/val2","O");};

		        var BISTypRemTrmWhtAvgDTO = WebSquare.xml.serialize(getInstanceNode("BISTypRemTrmWhtAvgDTO"));
		        callProFrameProcess("BIS-KOFIABOND","BISTypRemTrmWhtAvgSrchSO","selectList",BISTypRemTrmWhtAvgDTO, "respList");
        	}

