             **************************************************************************/
            function excelDownLoad() {
		    	var options = {
		    			fileName:divisionNm
		    		   ,type:"1"
		    		   ,colMerge:true
		    		   ,showProcess:true
		    		   ,showConfirm:false
		    		   ,footerColor:"#c0c0c0"
		    	};
		    	grdMain.advancedExcelDownload( options );
            }            

