			/**************************************************************************
			* function    : showData
			* Description : 떼이터 출력
			* Parameter   : null
			* Return      : null
			**************************************************************************/
			function showData() {
				if(aCnt <= 0) {grdMain.insertRow( 0 ); grdMain.setData( null );return;}
				var isOld = (getValue("BISTypRemTrmWhtAvgDTO/val2")=="N") ? false:true;
				var bondCnt = isOld ? 18:14;
				var grdData = new Array(bondCnt*12*3);

				var gIdx=0;

				for(var i=0 ; i<18 ; i++) {
					var xmlIdx=i+1;

					grdData[gIdx++]  = div[i];
					grdData[gIdx+11] = div[i];
					grdData[gIdx+23] = div[i];
					//alert("gIdx++ ="+ gIdx++ + "\ngrdData[gIdx++]=" + grdData[gIdx++] );
					if(isOld && i==15){
						grdData[gIdx++]  = "기타보증";
						grdData[gIdx+11] = "기타보증";
						grdData[gIdx+23] = "기타보증";

					}else {
						grdData[gIdx++]  = subDiv[i];
						grdData[gIdx+11] = subDiv[i];
						grdData[gIdx+23] = subDiv[i];					
					}
					grdData[gIdx++]="거래량";
					grdData[gIdx+11]="거래대금";
					grdData[gIdx+23]="수익률";

					for(var j=0 ; j<remain.length ; j++) {
						var node=getInstanceNode( "respList/root/message/BISTypRemTrmWhtAvgListDTO/BISTypRemTrmWhtAvgDTO[val1='"+xmlIdx+"' and val2='"+remain[j]+"']" );

						if(node==null) {
							grdData[gIdx++]="-";
							grdData[(gIdx+11)]="-";
							grdData[(gIdx+23)]="-";

						} else {
							grdData[gIdx++]=WebSquare.xml.getValue( node , "val3" );
							grdData[(gIdx+11)]=WebSquare.xml.getValue( node , "val4" );
							grdData[(gIdx+23)]=WebSquare.xml.getValue( node , "val5" );						
						}
					}
					if(!isOld){
						if(i==3||i==9||i==13||i==15){
							i+=1;
						}
					}

					gIdx+=24;
				}
				grdMain.setData( grdData );
			}



























