				for(var i=0 ; i<18 ; i++) {
					var xmlIdx=i+1;
					grdData[gIdx++]=div[i];
					grdData[gIdx+7]=div[i];
					grdData[gIdx+15]=div[i];
					grdData[gIdx++]=osubDiv[i];
					grdData[gIdx+7]=osubDiv[i];
					grdData[gIdx+15]=osubDiv[i];					
					grdData[gIdx++]="거래량";
